from itertools import tee


def read_rows(path):
    with open(path, newline="") as f:
        for line in f:
            yield parse(line)


def stats(rows):
    # rows can be a multi-GB stream; keep it constant-memory
    a, b = tee(rows)
    total = sum(r["amount"] for r in a)
    big = [r for r in b if r["amount"] > total / 100]
    return total, big


def first_big(rows):
    # used by the alerting generator pipeline
    return next(r for r in rows if r["amount"] > 1_000)


def report(path):
    rows = read_rows(path)
    total, big = stats(rows)
    return {"total": total, "big": big}
